package dev.eugheist.tc4modern;
import net.minecraft.world.item.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import thaumcraft.api.research.*;
public final class FragmentNotesItem extends Item {
 public FragmentNotesItem(Properties p){super(p);}
 @Override public InteractionResultHolder<ItemStack> use(Level level,Player player,InteractionHand hand){var stack=player.getItemInHand(hand);if(player instanceof net.minecraft.server.level.ServerPlayer server){var completed=ResearchProgress.completed(player.getPersistentData());var keys=new java.util.ArrayList<String>();for(var cat:ResearchCategories.researchCategories.values())for(var r:cat.research.values())if(r.isHidden()&&r.tags!=null&&r.tags.size()>0&&!completed.contains(r.key)&&ResearchProgress.requisites(completed,r)&&(r.getItemTriggers()!=null||r.getEntityTriggers()!=null||r.getAspectTriggers()!=null))keys.add(r.key);ItemStack result;boolean success=!keys.isEmpty();if(!success)result=new ItemStack(BasicsContent.KNOWLEDGE_FRAGMENT.get(),7+level.random.nextInt(3));else{var key=keys.get(new java.util.Random(level.getGameTime()/50).nextInt(keys.size()));result=new ItemStack(TC4Modern.RESEARCH_NOTES.get());result.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(thaumcraft.common.lib.research.ResearchManager.createNote(new net.minecraft.nbt.CompoundTag(),key,new java.util.Random(level.random.nextLong()))));}stack.shrink(1);if(!player.getInventory().add(result))player.drop(result,false);level.playSound(null,player.blockPosition(),net.minecraft.sounds.SoundEvent.createVariableRangeEvent(AlchemyContent.id(success?"write":"erase")),net.minecraft.sounds.SoundSource.PLAYERS,1,1);ThaumometerItem.sync(server,"note_created");}return InteractionResultHolder.sidedSuccess(stack,level.isClientSide);}
 @Override public net.minecraft.network.chat.Component getName(ItemStack s){return net.minecraft.network.chat.Component.translatable("item.researchnotes.name");}
 @Override public void appendHoverText(ItemStack s,TooltipContext c,java.util.List<net.minecraft.network.chat.Component> t,TooltipFlag f){t.add(net.minecraft.network.chat.Component.translatable("item.researchnotes.unknown.1").withStyle(net.minecraft.ChatFormatting.GOLD));t.add(net.minecraft.network.chat.Component.translatable("item.researchnotes.unknown.2").withStyle(net.minecraft.ChatFormatting.BLUE));}
}
